import {assessmentSuggestions,visibleSuggestions} from './dashboard-suggestions.mjs?v=20261108-evidence';
import {api,escape,requestId} from './workspace-shared.js';
export function createDashboardWidgets({getClasses,onChange}){
 let records=[],error='',loading=true,dialog,epoch=0,suggestions=[],suggestionsLoading=true,suggestionFailures=0;const hidden=new Set();
 const date=value=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(value));
 const item=row=>`<article class="dashboard-record"><div><strong>${escape(row.title)}</strong><small>${escape(row.learnerName)} · ${escape(row.className||'Class')}</small>${row.notes?`<p>${escape(row.notes)}</p>`:''}<small>${row.reviewDate?'Review '+escape(date(row.reviewDate+'T12:00:00')):date(row.createdAt)}${row.kind==='intervention'&&row.status==='resolved'?' · Resolved':''}</small></div>${row.kind==='intervention'?`<button class="text-button" type="button" data-record-status="${escape(row.id)}" data-status="${row.status==='active'?'resolved':'active'}">${row.status==='active'?'Mark resolved':'Reopen'}</button>`:''}</article>`;
 const proposal=row=>`<article class="dashboard-suggestion"><div class="dashboard-suggestion-heading"><strong>${escape(row.learnerName)}</strong><span>${row.demo?'Demo evidence':'For teacher review'}</span></div><small>${escape(row.className)}</small><h3>${escape(row.title)}</h3><p>${escape(row.facts[0])}</p><details><summary>Why this suggestion?</summary>${row.facts.slice(1).map(f=>`<p>${escape(f)}</p>`).join('')}<a href="${escape(row.href)}">Review assessment evidence ↗</a></details><div class="dashboard-suggestion-actions"><button type="button" class="teacher-button secondary" data-review-suggestion="${escape(row.key)}">${row.kind==='intervention'?'Review intervention':'Review award'}</button><button type="button" class="text-button" data-hide-suggestion="${escape(row.key)}">Hide for now</button></div></article>`;
 function suggestionHTML(kind){
  const rows=visibleSuggestions(suggestions,records,hidden).filter(s=>s.kind===kind);
  return `<div class="dashboard-suggestions"><h3>Suggestions to review${rows.length?' · '+rows.length:''}</h3>${suggestionsLoading?'<p>Checking assessment evidence…</p>':rows.length?rows.slice(0,2).map(proposal).join(''):'<p>No suggestions to review right now. You can always add your own record.</p>'}${rows.length>2?`<details><summary>More suggestions (${rows.length-2})</summary>${rows.slice(2).map(proposal).join('')}</details>`:''}${suggestionFailures?'<p role="status">Some classes could not be checked. <button type="button" class="text-button" data-retry-records>Retry suggestions</button></p>':''}<details class="dashboard-suggestion-rules"><summary>How suggestions work</summary><p>Review prompts use the last 42 days of recorded evidence. Skill prompts require at least 10 independent responses over two days; below 60% suggests reviewing support, and at least 90% suggests recognition. A gain of 20 percentage points with recent accuracy of at least 70% can suggest progress.</p><p>Quiz prompts use three first-attempt lesson quizzes. Published teacher ratings can suggest support after three learning ratings of 2/5 or below, or recognition after three effort ratings of 4/5 or above. Demo skill responses are labelled and use their sample days.</p><p>These are starting criteria for teacher review. Missing, absent, supported or unsubmitted work is not treated as failure. No record is created until you review and save it. “Hide for now” lasts until this dashboard is reloaded.</p></details></div>`;
 }
 function html(){return `<div class="dashboard-support-grid">${['intervention','award'].map(kind=>{const all=records.filter(r=>r.kind===kind),current=kind==='intervention'?all.filter(r=>r.status==='active'):all,rest=all.filter(r=>!current.slice(0,3).includes(r));return `<section class="today-panel dashboard-widget" aria-labelledby="dashboard-${kind}-title"><div class="today-panel-heading"><h2 id="dashboard-${kind}-title"><span class="dashboard-widget-icon" aria-hidden="true">${kind==='intervention'?'↗':'☆'}</span>${kind==='intervention'?'Interventions':'Awards'} <span class="dashboard-widget-count">${loading?'…':error?'':current.length}</span></h2><button type="button" class="text-button" data-new-record="${kind}">${kind==='intervention'?'+ Add intervention':'+ Record award'}</button></div><p>${kind==='intervention'?'Plan support and keep the next review in sight.':'Celebrate effort, progress and achievement.'}</p>${loading?'<p class="today-panel-empty">Loading records…</p>':error?`<p role="status">${escape(error)} <button type="button" class="text-button" data-retry-records>Try again</button></p>`:current.length?current.slice(0,3).map(item).join(''):`<p class="today-panel-empty">${kind==='intervention'?'No active interventions. Add a support plan when a learner needs one.':'No awards recorded yet. Recognise a learner’s next achievement here.'}</p>`}${rest.length?`<details class="dashboard-record-history"><summary>${kind==='intervention'?'Intervention history':'More awards'} (${rest.length})</summary>${rest.map(item).join('')}</details>`:''}${suggestionHTML(kind)}<small class="dashboard-widget-private">Your private teacher records</small></section>`;}).join('')}</div>`;}
 async function refresh(){
  const token=++epoch;suggestionsLoading=true;
  const [saved,evidence]=await Promise.all([api('/api/dashboard/records').then(value=>({value}),error=>({error})),Promise.allSettled(getClasses().map(async classroom=>{const [roster,timeline]=await Promise.all([api('/api/enrollment/classes/'+encodeURIComponent(classroom.id)+'/roster'),api('/api/lesson-feedback/classes/'+encodeURIComponent(classroom.id)+'/timeline')]);return assessmentSuggestions({classroom,students:roster.students,timeline});}))]);
  if(token!==epoch)return;
  if(saved.error)error=saved.error.message;else{records=Array.isArray(saved.value.records)?saved.value.records:[];error='';}
  suggestions=evidence.flatMap(result=>result.status==='fulfilled'?result.value:[]);suggestionFailures=evidence.filter(result=>result.status==='rejected').length;loading=suggestionsLoading=false;onChange();
 }
 function review(key,opener){const suggestion=visibleSuggestions(suggestions,records,hidden).find(s=>s.key===key);if(suggestion)open(suggestion.kind,opener,suggestion);}
 function hide(key){hidden.add(key);onChange();document.querySelector('[data-new-record="'+(suggestions.find(s=>s.key===key)?.kind||'intervention')+'"]')?.focus();}

 async function status(id,value,button){button.disabled=true;try{const data=await api('/api/dashboard/records',{action:'status',id,status:value});records=records.map(row=>row.id===id?data.record:row);onChange();document.querySelector('[data-new-record="intervention"]')?.focus();}catch(e){button.disabled=false;error=e.message;onChange();}}
 function open(kind,opener,suggestion){
  dialog?.remove();dialog=document.createElement('dialog');dialog.className='dashboard-record-dialog';dialog.setAttribute('aria-labelledby','dashboard-record-heading');
  const classes=getClasses();dialog.innerHTML=`<form><h2 id="dashboard-record-heading">${kind==='intervention'?'Add intervention':'Record award'}</h2><p>Your private teacher record for this learner.</p><label>Class<select name="classId" required>${classes.length?classes.map(c=>`<option value="${escape(c.id)}">${escape(c.name)}</option>`).join(''):'<option value="">Create a class first</option>'}</select></label><label>Learner<select name="learnerId" required disabled><option value="">Loading learners…</option></select></label><label>${kind==='intervention'?'Support focus':'Award'}<input name="title" required maxlength="160" placeholder="${kind==='intervention'?'e.g. Using evidence in paragraphs':'e.g. Resilience in writing'}"></label><label>${kind==='intervention'?'Plan and next steps':'Reason for recognition'}<textarea name="notes" maxlength="1200" rows="3"></textarea></label>${kind==='intervention'?'<label>Review date <span>(optional)</span><input name="reviewDate" type="date"></label>':''}<p role="alert" data-record-error></p><div class="dialog-actions"><button type="button" class="teacher-button secondary" data-record-cancel>Cancel</button><button type="submit" class="teacher-button" ${classes.length?'':'disabled'}>Save ${kind==='intervention'?'intervention':'award'}</button></div></form>`;
  document.body.append(dialog);const form=dialog.querySelector('form'),classField=form.elements.classId,learner=form.elements.learnerId,message=dialog.querySelector('[data-record-error]'),save=form.querySelector('[type=submit]');let generation=0;const id=requestId();
  if(suggestion){classField.value=suggestion.classId;classField.disabled=true;form.elements.title.value=suggestion.title.slice(0,160);form.elements.notes.value=suggestion.notes.slice(0,1200);const basis=document.createElement('aside');basis.className='dashboard-review-basis';basis.innerHTML='<strong>'+(suggestion.demo?'Demo evidence to review':'Suggested from assessment evidence')+'</strong>'+suggestion.facts.map(f=>'<p>'+escape(f)+'</p>').join('');form.querySelector('h2').after(basis);}
  const close=()=>dialog.close();dialog.querySelector('[data-record-cancel]').onclick=close;dialog.addEventListener('close',()=>{dialog.remove();document.querySelector('[data-new-record="'+kind+'"]')?.focus();},{once:true});
  async function roster(){const token=++generation;learner.disabled=save.disabled=true;message.textContent='';if(!classField.value){learner.innerHTML='<option value="">Create a class first</option>';return;}try{const data=await api('/api/enrollment/classes/'+encodeURIComponent(classField.value)+'/roster');if(token!==generation)return;learner.innerHTML=data.students.length?data.students.map(s=>`<option value="${escape(s.id)}">${escape(s.name)}</option>`).join(''):'<option value="">Add learners to this class first</option>';if(suggestion){const found=data.students.some(s=>s.id===suggestion.learnerId);learner.value=found?suggestion.learnerId:'';learner.disabled=true;save.disabled=!found;if(!found)message.textContent='This learner is no longer in the class. Refresh the dashboard to check the evidence again.';}else learner.disabled=save.disabled=!data.students.length;}catch(e){if(token!==generation)return;learner.innerHTML='<option value="">Learners unavailable</option>';message.textContent=e.message;}}
  classField.onchange=roster;form.onsubmit=async event=>{event.preventDefault();save.disabled=true;message.textContent='';try{const data=await api('/api/dashboard/records',{id,action:'create',...(suggestion?{suggestionKey:suggestion.key}:{}),kind,classId:classField.value,learnerId:learner.value,title:form.elements.title.value,notes:form.elements.notes.value,reviewDate:form.elements.reviewDate?.value||''});records=[data.record,...records.filter(row=>row.id!==id)];error='';loading=false;close();onChange();}catch(e){message.textContent=e.message;save.disabled=false;}};
  dialog.showModal();roster();
 }
 return {html,refresh,open,status,review,hide,clear(){epoch++;records=[];suggestions=[];hidden.clear();loading=suggestionsLoading=true;error='';dialog?.close();}};
}
